var vm = require('vm');
var fs = require('fs');
var util = require('util');
var EventEmitter = require('events').EventEmitter;

function funcWithReturnFromSnippet(js) {
    if (js.indexOf('return') === -1) {
        if (js.substring(js.length - 1) === ';') {
            js = js.substring(0, js.length - 1);
        }
        js = 'return (' + js + ')';
    }
    return (new Function(js));
}

function objCopy(obj) {
    var copy;
    if (Array.isArray(obj)) {
        copy = obj.slice();
    } else if (typeof (obj) === 'object') {
        copy = {};
        Object.keys(obj).forEach(function (k) {
            copy[k] = obj[k];
        });
    } else {
        copy = obj;
    }
    return copy;
}

function parseLookup(lookup, lookupDelim) {
    var bits = [];
    lookupDelim = lookupDelim || '.';
    var bit = '';
    var states = [null];
    var SUPPORTED_ESCAPES = {
        '\'': '\'',
        '"': '"',
        '\`': '\`',
        '\\': '\\',
        'n': '\n',
        'r': '\r',
        't': '\t',
        'v': '\v',
        'b': '\b',
        'f': '\f'
    };
    for (var i = 0; i < lookup.length; ++i) {
        var ch = lookup[i];
        if (ch === '\\' && i+1 < lookup.length) {
            var nextCh = lookup[i+1];
            var escapedCh = SUPPORTED_ESCAPES[nextCh];
            if (escapedCh !== undefined) {
                bit += escapedCh;
                i++;
                continue;
            }
        }
        switch (states[states.length - 1]) {
        case null:
            switch (ch) {
            case '"':
            case '\'':
                states.push(ch);
                bit += ch;
                break;
            case '[':
                states.push(ch);
                if (bit !== '') {
                    bits.push(bit);
                    bit = ''
                }
                bit += ch;
                break;
            case lookupDelim:
                if (bit !== '') {
                    bits.push(bit);
                    bit = ''
                }
                break;
            default:
                bit += ch;
                break;
            }
            break;
        case '[':
            bit += ch;
            switch (ch) {
            case '"':
            case '\'':
            case '[':
                states.push(ch);
                break;
            case ']':
                states.pop();
                if (states[states.length - 1] === null) {
                    var VALID_QUOTES = '"\'`';
                    var sQuote = bit[1];
                    var eQuote = bit.slice(-2, -1);
                    if (VALID_QUOTES.indexOf(sQuote) === -1 || sQuote !== eQuote) {
                        throw new Error(util.format('invalid bracketed lookup string: %j (must be of the form [\'...\'], ["..."], or [`...`])', bit));
                    }
                    bits.push(bit.slice(2, -2));
                    bit = '';
                }
                break;
            }
            break;
        case '"':
            bit += ch;
            if (ch === '"') {
                states.pop();
                if (states[states.length - 1] === null) {
                    bits.push(bit);
                    bit = '';
                }
            }
            break;
        case '\'':
            bit += ch;
            if (ch === '\'') {
                states.pop();
                if (states[states.length - 1] === null) {
                    bits.push(bit);
                    bit = '';
                }
            }
            break;
        }
    }
    if (bit !== '') {
        bits.push(bit);
        bit = '';
    }
    var negIntPat = /^-\d+$/;
    for (var i = 0; i < bits.length; i++) {
        if (negIntPat.test(bits[i])) {
            bits[i] = Number(bits[i]);
        }
    }
    return bits;
}

function lookupDatum(datum, lookup) {
    var d = datum;
    for (var i = 0; i < lookup.length; i++) {
        var bit = lookup[i];
        if (d === null) {
            return undefined;
        } else if (typeof (bit) === 'number' && bit < 0) {
            d = d[d.length + bit];
        } else {
            d = d[bit];
        }
        if (d === undefined) {
            return undefined;
        }
    }
    return d;
}

function main(argv) {
    var vm = require('vm');
    var opts;
    try {
        opts = parseArgv(argv);
    } catch (e) {
        console.warn('json: error: %s', e.message);
        return drainStdoutAndExit(1);
    }
    if (opts.help) {
        printHelp();
        return;
    }
    if (opts.version) {
        if (opts.outputMode === OM_JSON) {
            var v = {
                version: getVersion(),
                author: 'Trent Mick',
                project: 'https://github.com/trentm/json'
            };
            console.log(JSON.stringify(v, null, opts.jsonIndent));
        } else {
            console.log('json ' + getVersion());
            console.log('written by Trent Mick');
            console.log('https://github.com/trentm/json');
        }
        return;
    }
    var lookupStrs = opts.args;
    var execVm = Boolean(process.env.JSON_EXEC && process.env.JSON_EXEC === 'vm');
    var condFuncs = [];
    if (!execVm) {
        for (var i = 0; i < opts.condSnippets.length; i++) {
            condFuncs[i] = funcWithReturnFromSnippet(opts.condSnippets[i]);
        }
    }
    var condScripts = [];
    if (execVm) {
        for (var i = 0; i < opts.condSnippets.length; i++) {
            condScripts[i] = vm.createScript(opts.condSnippets[i]);
        }
    }
    var cond = Boolean(condFuncs.length + condScripts.length);
    var exeFuncs = [];
    if (!execVm) {
        for (var i = 0; i < opts.exeSnippets.length; i++) {
            exeFuncs[i] = new Function(opts.exeSnippets[i]);
        }
    }
    var exeScripts = [];
    if (execVm) {
        for (var i = 0; i < opts.exeSnippets.length; i++) {
            exeScripts[i] = vm.createScript(opts.exeSnippets[i]);
        }
    }
    var exe = Boolean(exeFuncs.length + exeScripts.length);
    try {
        var lookups = lookupStrs.map(function (lookup) {
            return parseLookup(lookup, opts.lookupDelim);
        });
    } catch (e) {
        console.warn('json: error: %s', e.message);
        return drainStdoutAndExit(1);
    }
    getInput(opts, function (err, buffer, filename) {
        if (err) {
            console.warn('json: error: %s', err.message);
            return drainStdoutAndExit(1);
        }
        while (true) {
            if (buffer.slice(0, 5) === 'HTTP/') {
                var index = buffer.indexOf('\r\n\r\n');
                var sepLen = 4;
                if (index == -1) {
                    index = buffer.indexOf('\n\n');
                    sepLen = 2;
                }
                if (index != -1) {
                    if (!opts.dropHeaders) {
                        emit(buffer.slice(0, index + sepLen));
                    }
                    var is100Continue = (buffer.slice(0, 21) === 'HTTP/1.1 100 Continue');
                    buffer = buffer.slice(index + sepLen);
                    if (is100Continue) {
                        continue;
                    }
                }
            }
            break;
        }
        parseChunk(buffer, null, filename, false);
    });

    function parseChunk(chunk, obj, filename, inPlace, headers) {
        if (!chunk.length) {
            return;
        }
        var input = parseInput(chunk, obj, opts.group, opts.merge);
        if (input.error) {
            if (!opts.quiet) {
                var details = '';
                var normBuffer = chunk.replace(/\r\n|\n|\r/, '\n');
                try {
                    json_parse(normBuffer);
                    details = input.error;
                } catch (err) {
                    var at = err.at - 1;
                    var lines = chunk.split('\n');
                    var line, col, pos = 0;
                    for (line = 0; line < lines.length; line++) {
                        pos += lines[line].length + 1;
                        if (pos > at) {
                            col = at - (pos - lines[line].length - 1);
                            break;
                        }
                    }
                    var spaces = '';
                    for (var i = 0; i < col; i++) {
                        spaces += '.';
                    }
                    details = err.message + ' at line ' + (line + 1) + ', column ' + (col + 1) + ':\n        ' + lines[line] + '\n        ' + spaces + '^';
                }
                console.warn('json: error: %s is not JSON: %s', filename ? '"' + filename + '"' : 'input', details);
            }
            if (!opts.validate) {
                emit(chunk);
                if (chunk.length && chunk[chunk.length - 1] !== '\n') {
                    emit('\n');
                }
            }
            return drainStdoutAndExit(1);
        }
        if (opts.validate) {
            return drainStdoutAndExit(0);
        }
        var data = input.datum;
        if (opts.items) {
            if (!Array.isArray(data)) {
                var key;
                var array = [];
                for (key in data) {
                    if (data.hasOwnProperty(key)) {
                        array.push({
                          key: key,
                          value: data[key]
                        });
                    }
                }
                data = array;
            }
        }
        if (exe) {
            if (opts.array || (opts.array === null && Array.isArray(data))) {
                var arrayified = false;
                if (!Array.isArray(data)) {
                    arrayified = true;
                    data = [data];
                }
                for (var i = 0; i < data.length; i++) {
                    var datum = data[i];
                    for (var j = 0; j < exeFuncs.length; j++) {
                        exeFuncs[j].call(datum);
                    }
                    for (var j = 0; j < exeScripts.length; j++) {
                        exeScripts[j].runInNewContext(datum);
                    }
                }
                if (arrayified) {
                    data = data[0];
                }
            } else {
                for (var j = 0; j < exeFuncs.length; j++) {
                    exeFuncs[j].call(data);
                }
                for (var j = 0; j < exeScripts.length; j++) {
                    exeScripts[j].runInNewContext(data);
                }
            }
        }
        if (cond) {
            if (opts.array || (opts.array === null && Array.isArray(data))) {
                var arrayified = false;
                if (!Array.isArray(data)) {
                    arrayified = true;
                    data = [data];
                }
                var filtered = [];
                for (var i = 0; i < data.length; i++) {
                    var datum = data[i];
                    var datumCopy = objCopy(datum);
                    var keep = true;
                    for (var j = 0; j < condFuncs.length; j++) {
                        if (!condFuncs[j].call(datumCopy)) {
                            keep = false;
                            break;
                        }
                    }
                    if (keep) {
                        for (var j = 0; j < condScripts.length; j++) {
                            if (!condScripts[j].runInNewContext(datumCopy)) {
                                keep = false;
                                break;
                            }
                        }
                        if (keep) {
                            filtered.push(datum);
                        }
                    }
                }
                if (arrayified) {
                    data = (filtered.length ? filtered[0] : []);
                } else {
                    data = filtered;
                }
            } else {
                var keep = true;
                var dataCopy = objCopy(data);
                for (var j = 0; j < condFuncs.length; j++) {
                    if (!condFuncs[j].call(dataCopy)) {
                        keep = false;
                        break;
                    }
                }
                if (keep) {
                    for (var j = 0; j < condScripts.length; j++) {
                        if (!condScripts[j].runInNewContext(dataCopy)) {
                            keep = false;
                            break;
                        }
                    }
                }
                if (!keep) {
                    data = undefined;
                }
            }
        }
        var lookupsAreIndeces = false;
        if (lookups.length) {
            if (opts.array) {
                if (!Array.isArray(data)) data = [data];
                var table = [];
                for (var j = 0; j < data.length; j++) {
                    var datum = data[j];
                    var row = {};
                    for (var i = 0; i < lookups.length; i++) {
                        var lookup = lookups[i];
                        var value = lookupDatum(datum, lookup);
                        if (value !== undefined) {
                            row[lookup.join('.')] = value;
                        }
                    }
                    table.push(row);
                }
                data = table;
            } else {
                if (Array.isArray(data)) {
                    lookupsAreIndeces = true;
                    for (var i = 0; i < lookups.length; i++) {
                        if (lookups[i].length !== 1 || isNaN(Number(lookups[i]))) {
                            lookupsAreIndeces = false;
                            break;
                        }
                    }
                }
                var row = {};
                for (var i = 0; i < lookups.length; i++) {
                    var lookup = lookups[i];
                    var value = lookupDatum(data, lookup);
                    if (value !== undefined) {
                        row[lookup.join('.')] = value;
                    }
                }
                data = row;
            }
        }
        if (opts.outputKeys) {
            data = Object.keys(data);
        }
        var datasets = [];
        if (opts.outputMode === OM_JSON) {
            if (lookups.length === 1 && !opts.array) {
                data = data[lookups[0].join('.')];
            } else if (lookupsAreIndeces) {
                var flattened = [];
                for (var i = 0; i < lookups.length; i++) {
                    var lookupStr = lookups[i].join('.');
                    if (data.hasOwnProperty(lookupStr)) {
                        flattened.push(data[lookupStr]);
                    }
                }
                data = flattened;
            }
            datasets.push([data, '\n', false]);
        } else if (lookups.length) {
            if (opts.array) {
                for (var j = 0; j < data.length; j++) {
                    var row = data[j];
                    for (var i = 0; i < lookups.length - 1; i++) {
                        datasets.push([row[lookups[i].join('.')], opts.delim, true]);
                    }
                    datasets.push([row[lookups[i].join('.')], '\n', true]);
                }
            } else {
                for (var i = 0; i < lookups.length; i++) {
                    datasets.push([data[lookups[i].join('.')], '\n', false]);
                }
            }
        } else if (opts.array) {
            if (!Array.isArray(data)) data = [data];
            for (var j = 0; j < data.length; j++) {
                datasets.push([data[j], '\n', false]);
            }
        } else {
            datasets.push([data, '\n', false]);
        }
        printDatasets(datasets, inPlace ? filename : undefined, headers, opts);
    }
}

if (require.main === module) {
